package com.attendance.repository;
import com.attendance.model.Attendance; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; import java.time.LocalDate;
public interface AttendanceRepository extends JpaRepository<Attendance,Long>{ List<Attendance> findByStudent_Id(Long id); List<Attendance> findByStudent_IdAndSubject_IdOrderByAttendanceDateDesc(Long studentId,Long subjectId); List<Attendance> findBySubject_Id(Long id); List<Attendance> findByAttendanceDate(LocalDate date); List<Attendance> findByMarkedBy(String markedBy); Optional<Attendance> findByStudent_IdAndSubject_IdAndAttendanceDate(Long studentId,Long subjectId,LocalDate date); Optional<Attendance> findBySessionIdAndStudent_Id(Long sessionId,Long studentId); void deleteByStudent_Id(Long studentId); void deleteBySubject_Id(Long subjectId); }
